//! Monte Carlo consistency checks for the EKF.
//!
//! A correctly tuned filter on data generated by its own model should have
//! average NEES close to the state dimension (4) and average NIS close to the
//! measurement dimension (2).

use fusetrack::{sim, Ekf, Radar, State};
use nalgebra::{Matrix4, Vector2, Vector4};
use rand::{rngs::StdRng, SeedableRng};
use rand_distr::{Distribution, Normal};

const DT: f64 = 1.0;
const STEPS: usize = 100;
const BURN_IN: usize = 10;
const RUNS: u64 = 100;
const SIGMA_ACCEL: f64 = 2.0;

fn radar() -> Radar {
    Radar {
        pos: Vector2::new(0.0, 0.0),
        sigma_r: 15.0,
        sigma_b: 0.003,
    }
}

/// Returns (mean NEES, mean NIS, final-position RMSE, raw-measurement RMSE).
fn run_monte_carlo() -> (f64, f64, f64, f64) {
    let radar = radar();
    let p0 = Matrix4::from_diagonal(&Vector4::new(100.0, 100.0, 25.0, 25.0));
    let p0_std = Vector4::new(10.0, 10.0, 5.0, 5.0);

    let (mut nees_sum, mut nees_n) = (0.0, 0usize);
    let (mut nis_sum, mut nis_n) = (0.0, 0usize);
    let (mut filt_sq, mut raw_sq, mut err_n) = (0.0, 0.0, 0usize);

    for seed in 0..RUNS {
        let mut rng = StdRng::seed_from_u64(seed);
        let x0 = State::new(6000.0, 3000.0, -25.0, 10.0);
        let truth = sim::simulate_trajectory(x0, DT, STEPS, SIGMA_ACCEL, &mut rng);

        // Initial estimate drawn consistently with P0.
        let unit = Normal::new(0.0, 1.0).unwrap();
        let init_err = Vector4::from_fn(|i, _| p0_std[i] * unit.sample(&mut rng));
        let mut ekf = Ekf::new(x0 + init_err, p0, SIGMA_ACCEL);

        for (k, truth_k) in truth.iter().enumerate().skip(1) {
            ekf.predict(DT);
            let z = radar.measure(truth_k, &mut rng);
            let nis = ekf.update_radar(&z, &radar).expect("update applied");

            if k > BURN_IN {
                let e = ekf.x - truth_k;
                let nees = (e.transpose() * ekf.p.try_inverse().unwrap() * e)[0];
                nees_sum += nees;
                nees_n += 1;
                nis_sum += nis;
                nis_n += 1;

                // Compare filter position error with the raw measurement's.
                filt_sq += e[0] * e[0] + e[1] * e[1];
                let (s, c) = z.bearing.sin_cos();
                let raw = Vector2::new(z.range * c, z.range * s) + radar.pos;
                raw_sq += (raw[0] - truth_k[0]).powi(2) + (raw[1] - truth_k[1]).powi(2);
                err_n += 1;
            }
        }
    }

    (
        nees_sum / nees_n as f64,
        nis_sum / nis_n as f64,
        (filt_sq / err_n as f64).sqrt(),
        (raw_sq / err_n as f64).sqrt(),
    )
}

#[test]
fn ekf_is_statistically_consistent() {
    let (nees, nis, _, _) = run_monte_carlo();
    println!("mean NEES = {nees:.3} (expect ~4), mean NIS = {nis:.3} (expect ~2)");
    assert!((3.2..=5.0).contains(&nees), "mean NEES {nees} out of range");
    assert!((1.7..=2.4).contains(&nis), "mean NIS {nis} out of range");
}

#[test]
fn ekf_beats_raw_measurements() {
    let (_, _, filt_rmse, raw_rmse) = run_monte_carlo();
    println!("position RMSE: filter {filt_rmse:.2} m vs raw {raw_rmse:.2} m");
    assert!(filt_rmse < raw_rmse);
}
